import{_ as t,a as s}from"./chunks/ugso_template_condition.CrfWfEWi.js";import{_ as n,o as r,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const i="/assets/blocks-for-ha/blocks/fr/ugso_template_time_window.png",l="/assets/blocks-for-ha/blocks/fr/ugso_template_change.png",c="/assets/blocks-for-ha/blocks/fr/ugso_entity_value.png",u="/assets/blocks-for-ha/blocks/fr/ugso_entity_value_dynamic.png",d="/assets/blocks-for-ha/blocks/fr/ugso_entity_snapshot.png",p="/assets/blocks-for-ha/blocks/fr/ugso_automation_control.png",m="/assets/blocks-for-ha/blocks/fr/ugso_app_control.png",g="/assets/blocks-for-ha/blocks/fr/ugso_template_builder.png",b="/assets/blocks-for-ha/blocks/fr/ugso_template_linebreak.png",h="/assets/blocks-for-ha/blocks/fr/ugso_number_format.png",v="/assets/blocks-for-ha/blocks/fr/ugso_template_conditional.png",A=JSON.parse('{"title":"Valeurs système et constructeur de templates","description":"Valeurs d’entités partagées, commandes d’applications et d’automatisations, templates lisibles.","frontmatter":{"title":"Valeurs système et constructeur de templates","description":"Valeurs d’entités partagées, commandes d’applications et d’automatisations, templates lisibles."},"headers":[],"relativePath":"fr/projects/blocks-for-ha/system-template.md","filePath":"fr/projects/blocks-for-ha/system-template.md","lastUpdated":1792754181000}'),f={name:"fr/projects/blocks-for-ha/system-template.md"};function _(x,e,k,C,y,S){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="valeurs-systeme-et-constructeur-de-templates" tabindex="-1">Valeurs système et constructeur de templates <a class="header-anchor" href="#valeurs-systeme-et-constructeur-de-templates" aria-label="Permalink to &quot;Valeurs système et constructeur de templates&quot;">​</a></h1><p>Depuis <strong>0.1.62</strong>, entièrement traduit en DE/EN/FR. Les blocs Système fournissent aussi les valeurs des Templates. Réutiliser les blocs texte, mathématiques et variables existants.</p><p>Depuis <strong>0.1.63</strong>, Template possède des entrées de valeurs directes sur des lignes verticales, comme Écrire un fichier dans ioBroker. Tous les blocs Template sont sans engrenage ; les entrées correspondent à leur type.</p><h2 id="templates-par-usage-depuis-0-1-64" tabindex="-1">Templates par usage depuis 0.1.64 <a class="header-anchor" href="#templates-par-usage-depuis-0-1-64" aria-label="Permalink to &quot;Templates par usage depuis 0.1.64&quot;">​</a></h2><p>Ces blocs sont dans <strong>Templates</strong>, sans engrenage. <strong>Composer du texte</strong> produit du texte pour les messages. <strong>Heure dans la plage</strong> et <strong>Vérifier la variation</strong> renvoient un booléen et se branchent directement sur « Seulement si », « si », « et » ou « ou ». <strong>Choisir une valeur – si/sinon</strong> propose des types de résultat avec les entrées adaptées.</p><h3 id="heure-dans-la-plage" tabindex="-1">Heure dans la plage <a class="header-anchor" href="#heure-dans-la-plage" aria-label="Permalink to &quot;Heure dans la plage&quot;">​</a></h3><p>Saisir début et fin en <code>HH:MM</code> ou <code>HH:MM:SS</code>. L’heure locale actuelle de HA est vérifiée : <strong>début inclus</strong>, <strong>fin exclue</strong>. Avec 10:00 et 13:00, cela correspond à <code>&#39;10:00:00&#39; &lt;= now().strftime(&#39;%H:%M:%S&#39;) &lt; &#39;13:00:00&#39;</code>. De 22:00 à 06:00 fonctionne en passant minuit. Des bornes égales donnent faux. C’est une condition, pas un déclencheur horaire.</p><p><img src="'+i+'" alt="Heure dans la plage"></p><h3 id="verifier-la-variation" tabindex="-1">Vérifier la variation <a class="header-anchor" href="#verifier-la-variation" aria-label="Permalink to &quot;Vérifier la variation&quot;">​</a></h3><p><strong>Hausse supérieure à 10</strong>, <strong>baisse supérieure à 20</strong> vérifie <code>nouvelle valeur - ancienne valeur &gt; 10</code> ou <code>&lt; -20</code>. Saisir la baisse comme une amplitude positive. Exactement +10 ou −20 ne satisfait pas la condition.</p><p>Laisser Ancienne valeur et Nouvelle valeur vides utilise <code>trigger.from_state.state</code> et <code>trigger.to_state.state</code>, pour les déclencheurs d’état. Un déclencheur ou ancien état absent donne faux, comme un ancien état <code>unknown</code>, <code>unavailable</code> ou <code>none</code>. On peut aussi brancher des variables enregistrées ou des valeurs d’entités Système. Les deux valeurs utilisent <code>float(0)</code>, comme l’exemple : le texte non numérique vaut 0. Une nouvelle valeur absente vaut aussi 0. Vérifier séparément la nouvelle valeur si ce comportement ne convient pas.</p><p><img src="'+l+'" alt="Vérifier la variation"></p><h3 id="code-jinja-personnalise" tabindex="-1">Code Jinja personnalisé <a class="header-anchor" href="#code-jinja-personnalise" aria-label="Permalink to &quot;Code Jinja personnalisé&quot;">​</a></h3><p><strong>Jinja – code personnalisé</strong> accepte un template complet pour une entrée de valeur ; <strong>Jinja – condition personnalisée</strong> accepte un template booléen complet. Les instructions multilignes <code>{% if %}</code>, <code>{% set %}</code> et <code>{% else %}</code> sont conservées. Seule une expression unique <code>{{ ... }}</code> peut constituer une partie de Composer du texte ; brancher les templates avec instructions directement sur leur destination.</p><p><img src="'+t+'" alt="Code personnalisé"><img src="'+s+'" alt="Condition personnalisée"></p><p>Les entrées de code libre équivalentes ont été retirées de <strong>Jinja (expérimental)</strong> et figurent une seule fois dans <strong>Templates</strong>. La catégorie expérimentale garde le constructeur Jinja décomposable. Ses parties modifient des expressions Jinja et ne sont pas des actions HA supplémentaires. Les anciens blocs de projet et le code original importé restent lisibles.</p><p><strong>Contrôler l’application</strong> et <strong>Contrôler l’automatisation</strong> sont dans <strong>Système</strong>. Depuis 0.1.64, ils ont deux lignes comme Contrôler l’instance dans ioBroker : sélection en haut, Action en dessous. Les applications HA et entités d’automatisation remplacent les instances ioBroker.</p><h2 id="systeme" tabindex="-1">Système <a class="header-anchor" href="#systeme" aria-label="Permalink to &quot;Système&quot;">​</a></h2><p>Les changements dans l’engrenage modifient immédiatement le bloc principal : ajouter affiche une ligne, retirer la masque et adapte la taille, même avec le dialogue ouvert.</p><table tabindex="0"><thead><tr><th>Bloc</th><th>Utilisation</th></tr></thead><tbody><tr><td>ID de l’entité</td><td>Choisir une entité et brancher son ID sur un autre bloc.</td></tr><tr><td>Valeur de l’entité</td><td>Sélection HA fixe : état, nom, unité, attribut, dernière modification ou actualisation.</td></tr><tr><td>Valeur de l’ID d’entité</td><td>Brancher un ID provenant d’un bloc ID d’entité, texte ou variable.</td></tr><tr><td>Lire une fois dans une variable</td><td>Enregistrer un instantané puis exécuter les actions contenues. Ce n’est pas un déclencheur. La variable reste disponible pour les étapes HA suivantes.</td></tr><tr><td>Contrôler l’application</td><td>Démarrer, arrêter ou redémarrer. Choisir une application installée via Supervisor ou saisir son identifiant.</td></tr><tr><td>Contrôler l’automatisation</td><td>Activer, désactiver, basculer ou exécuter maintenant.</td></tr></tbody></table><p><img src="'+c+'" alt="Valeur d’entité"><img src="'+u+'" alt="Valeur dynamique"><img src="'+d+'" alt="Instantané"><img src="'+p+'" alt="Commande d’automatisation"><img src="'+m+'" alt="Commande d’application"></p><p>Choisir <strong>Attribut</strong> et saisir son nom ; la ligne correspondante apparaît automatiquement. Les états sont souvent du texte. Utiliser <strong>Conversion → en nombre</strong> avant les calculs si nécessaire. Les attributs et horodatages absents donnent <code>none</code> ; un état absent donne <code>unknown</code> selon HA. <strong>Valeur de remplacement</strong> permet de traiter ces cas.</p><p>L’engrenage de <strong>Contrôler l’automatisation</strong> ajoute <strong>Brancher l’ID d’entité</strong>, <strong>Vérifier les conditions</strong> et <strong>Arrêter les actions en cours</strong>. L’ID branché remplace la sélection fixe. Les conditions concernent « exécuter maintenant », l’arrêt concerne « désactiver ». Sans option explicite, HA applique ses valeurs par défaut : exécuter ignore les conditions, désactiver arrête les actions en cours. Activer permet d’écouter les déclencheurs sans exécuter immédiatement les actions.</p><p><strong>Contrôler l’application</strong> nécessite Supervisor et les droits administrateur. L’application reçoit un accès en lecture à Supervisor pour la sélection ; démarrage/arrêt/redémarrage se produisent uniquement lors de l’exécution de l’automatisation exportée dans HA. Sans Supervisor, l’identifiant reste modifiable mais l’action est indisponible. Export : <code>hassio.app_start</code>, <code>hassio.app_stop</code>, <code>hassio.app_restart</code> avec <code>data.app</code>.</p><h2 id="construire-un-template" tabindex="-1">Construire un Template <a class="header-anchor" href="#construire-un-template" aria-label="Permalink to &quot;Construire un Template&quot;">​</a></h2><ol><li>Brancher <strong>Templates → Composer du texte</strong> sur une entrée texte, par exemple « Message ».</li><li>Brancher un <strong>Texte</strong> normal directement sur <strong>Partie 1</strong>.</li><li>Brancher une <strong>Valeur d’entité de Système</strong> ou un <strong>Format du nombre</strong> directement sur <strong>Partie 2</strong>.</li><li>Remplir la dernière entrée ajoute automatiquement une autre entrée. L’ordre de haut en bas détermine la sortie. Les entrées vides sont ignorées et conservent leur position pour annuler/rétablir.</li></ol><p>Exemple : texte <code>Température : </code> → valeur de <code>sensor.temperature</code> via <strong>Format du nombre</strong>, avec le nombre mathématique <code>1</code> pour les décimales → texte <code> °C</code>. Résultat possible : <code>Température : 21.6 °C</code>.</p><p><img src="'+g+'" alt="Template"><img src="'+b+'" alt="Nouvelle ligne comme valeur"><img src="'+h+'" alt="Format du nombre"><img src="'+v+'" alt="Sortie conditionnelle"></p><table tabindex="0"><thead><tr><th>Complément</th><th>Signification</th></tr></thead><tbody><tr><td>Format du nombre</td><td>0–10 décimales avec un point décimal. Utiliser un nombre mathématique pour leur quantité. Brancher le remplacement directement sur son entrée facultative ; sinon texte vide pour les nombres invalides.</td></tr><tr><td>Valeur sinon</td><td>Remplacement pour <code>unknown</code>, <code>unavailable</code>, <code>none</code> et texte vide. Conserve <code>0</code> et <code>false</code>.</td></tr><tr><td>Nouvelle ligne</td><td>Commencer une nouvelle ligne à cet endroit.</td></tr><tr><td>Choisir une valeur – si/sinon</td><td>Choisir le type : Valeur, Texte, Nombre ou Booléen. Brancher un booléen sur « si » et des valeurs adaptées sur « alors » et « sinon ». Utiliser Composer du texte pour plusieurs parties. Une branche vide produit du texte vide pour Valeur/Texte ; Nombre/Booléen exigent les deux branches.</td></tr></tbody></table><p>Brancher le formatage directement autour de la valeur concernée. Texte, nombres, valeurs d’entités, nouvelles lignes et valeurs conditionnelles utilisent des connexions de valeurs ; « si » accepte uniquement les blocs booléens. Les chaînes d’actions ne se branchent pas sur ces entrées. Les caractères Jinja d’un texte normal restent littéraux. Les anciennes chaînes Afficher sont converties automatiquement lors du chargement dans l’éditeur, en conservant branches et parties désactivées. Les anciens types restent lisibles pour la compatibilité mais ne figurent plus dans le menu.</p><p><strong>Clic droit → Aperçu du template / Jinja</strong> affiche le code produit et demande à HA le rendu des valeurs actuelles. Cet instantané n’exécute aucune action et nécessite une connexion HA accessible. Sans connexion, l’aperçu est explicitement indisponible. Les identifiants d’accès restent sur le serveur. Le JSON du projet conserve les blocs, connexions et options d’engrenage. Le YAML contient du Jinja natif ; son import peut produire un bloc template libre. HA peut interpréter les nombres ou listes purs d’un résultat comme des valeurs natives.</p><p>Références : <a href="https://www.home-assistant.io/docs/automation/automation_integration_actions/" target="_blank" rel="noreferrer">actions d’automatisation HA</a>, <a href="https://www.home-assistant.io/integrations/hassio/" target="_blank" rel="noreferrer">Supervisor</a>, <a href="https://www.home-assistant.io/docs/templating/" target="_blank" rel="noreferrer">Jinja dans HA</a>.</p>',32)])])}const T=n(f,[["render",_]]);export{A as __pageData,T as default};
